const d = $input.first().json.body ?? $input.first().json;

const brl = (v) => {
  const [inteiro, centavos] = Math.abs(v).toFixed(2).split('.');
  const milhar = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (v < 0 ? '-R$ ' : 'R$ ') + milhar + ',' + centavos;
};

const anuncio = d.anuncio || 'Anuncio sem identificacao';
const gasto = Number(d.gasto) || 0;
const faturamento = Number(d.faturamento) || 0;
const vendas = Number(d.vendas_qtd) || 0;
const cliques = Number(d.cliques) || 0;
const impressoes = Number(d.impressoes) || 0;
// limite de ROAS aceitavel: vem no payload ou cai no padrao 2.0
const roasMinimo = Number(d.roas_minimo) || 2;

const roas = gasto > 0 ? faturamento / gasto : 0;
const cpa = vendas > 0 ? gasto / vendas : 0;
const ticketMedio = vendas > 0 ? faturamento / vendas : 0;
const resultado = faturamento - gasto;
const taxaConversao = cliques > 0 ? (vendas / cliques) * 100 : null;
// CTR so existe se vierem impressoes; sem elas fica null e o banco guarda NULL
const ctr = impressoes > 0 ? (cliques / impressoes) * 100 : null;

// quanto de faturamento ainda falta para o anuncio bater o ROAS minimo
const gapFaturamento = Math.max(gasto * roasMinimo - faturamento, 0);
const vendasFaltantes = ticketMedio > 0 ? Math.ceil(gapFaturamento / ticketMedio) : 0;

const classificacao = roas >= roasMinimo ? 'saudavel' : roas >= 1 ? 'atencao' : 'critico';

return [{
  json: {
    anuncio,
    data: $now.toFormat('dd/MM/yyyy HH:mm'),
    gasto,
    faturamento,
    vendas_qtd: vendas,
    cliques,
    impressoes,
    roas: Number(roas.toFixed(2)),
    roas_minimo: roasMinimo,
    cpa: Number(cpa.toFixed(2)),
    ticket_medio: Number(ticketMedio.toFixed(2)),
    resultado: Number(resultado.toFixed(2)),
    taxa_conversao: taxaConversao === null ? null : Number(taxaConversao.toFixed(2)),
    ctr: ctr === null ? null : Number(ctr.toFixed(2)),
    gap_faturamento: Number(gapFaturamento.toFixed(2)),
    vendas_faltantes: vendasFaltantes,
    classificacao,
    gasto_fmt: brl(gasto),
    faturamento_fmt: brl(faturamento),
    resultado_fmt: brl(resultado),
    cpa_fmt: brl(cpa),
    ticket_medio_fmt: brl(ticketMedio),
    gap_fmt: brl(gapFaturamento),
  },
}];

